    console.log("ledgerAccount not in supplier response, fetching 2400...");
    const la = await api("GET", "/ledger/account?number=2400&fields=*");
    liabAcctId = la.values[0]?.id;
    if (!liabAcctId) throw new Error("account 2400 not found");
